CREATE TABLE privacy_consents(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,subject_student_id uuid,consenting_user_id uuid NOT NULL,policy_version varchar(100) NOT NULL,purpose_code varchar(40) NOT NULL,legal_basis varchar(40) NOT NULL,granted boolean NOT NULL,captured_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,FOREIGN KEY(tenant_id,consenting_user_id) REFERENCES tenant_memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,subject_student_id) REFERENCES student_profiles(tenant_id,id));
CREATE INDEX consent_scope_idx ON privacy_consents(tenant_id,consenting_user_id,subject_student_id,purpose_code);
CREATE TABLE data_subject_requests(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,requester_user_id uuid NOT NULL,subject_student_id uuid,type varchar(20) NOT NULL CHECK(type IN ('ACCESS','CORRECT','EXPORT','ERASE','WITHDRAW')),status varchar(20) NOT NULL DEFAULT 'RECEIVED' CHECK(status IN ('RECEIVED','VERIFIED','APPROVED','REJECTED','COMPLETED')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,requester_user_id) REFERENCES tenant_memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,subject_student_id) REFERENCES student_profiles(tenant_id,id));
